CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS properties (id text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), name text NOT NULL, address text NOT NULL);
CREATE TABLE IF NOT EXISTS rooms (id text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), property_id text NOT NULL REFERENCES properties(id), name text NOT NULL, UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS tenancies (id text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), room_id text UNIQUE NOT NULL REFERENCES rooms(id), name text NOT NULL, phone text NOT NULL, rent integer NOT NULL CHECK(rent>0), due_day integer NOT NULL CHECK(due_day BETWEEN 1 AND 28), start_month text NOT NULL);
CREATE TABLE IF NOT EXISTS charges (id text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), tenancy_id text NOT NULL REFERENCES tenancies(id), month text NOT NULL, amount integer NOT NULL CHECK(amount>=0), UNIQUE(tenancy_id,month));
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY, owner text NOT NULL REFERENCES accounts(id), tenancy_id text NOT NULL REFERENCES tenancies(id), amount integer NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('Cash','EFT','Bank deposit')), paid_on date NOT NULL, reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), void_reason text, voided_at timestamptz);
